// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 v) public {
        // Admissible domain: any amount (bounded so vm.deal can fund it).
        v = bound(v, 0, type(uint128).max);

        // Fund the contract with exactly v, so withdraw(v) succeeds in the reference.
        vm.deal(address(c), v);
        uint256 before = address(c).balance;

        // Owner is the deployer (this test contract). Call withdraw(v); accept revert as
        // legitimate behavior via try/catch so the reference never spuriously fails.
        vm.prank(address(this));
        bool ok;
        try c.withdraw(v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever withdraw(v) completes successfully, the contract's
        // balance decreased by exactly v (the ether actually left the contract).
        assertTrue(!ok || address(c).balance == before - v);
    }
}
